"Клан мифологии следующего сезона. Он откроется, когда Орден соберёт Алатырь-камень и Кощей снова расколет его.":"अगले सीज़न की पौराणिक कथा का दल। यह तब खुलेगा जब संघ अलातिर पत्थर जोड़ लेगा और कोश्चेई उसे फिर तोड़ देगा।",
"Клан можно выбрать с {0} уровня":"दल लेवल {0} से चुन सकते हो",
"Выбери клан":"अपना दल चुनो",
"У каждой мифологии Перепутицы — свой клан Ордена. Кланы держат Святилища: поставь своего духа защитником — и Святилище окрасится цветом твоего клана, а тебе каждый день будет приходить дань. Выбор — навсегда.":"महा-उलझन की हर पौराणिक कथा का संघ में अपना दल है। दल पवित्र स्थान थामे रखते हैं: अपनी आत्मा को रक्षक बनाकर खड़ा करो — पवित्र स्थान तुम्हारे दल के रंग में रंग जाएगा, और तुम्हें हर दिन नज़राना मिलेगा। चुनाव हमेशा के लिए है।",
"Позже":"बाद में",
"Выбор — навсегда: сменить клан потом нельзя.":"चुनाव हमेशा के लिए है: बाद में दल नहीं बदल सकते।",
