"Оберег":"ताबीज़",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"मंत्र पढ़ी जड़ी-बूटी की पोटली। आत्मा को पकड़ने के लिए उस पर फेंको।",
"Серебряный оберег":"चाँदी का ताबीज़",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"चाँदी आत्माओं को ज़्यादा मज़बूती से थामती है। पकड़ने का मौक़ा ×1.5।",
"Золотой оберег":"सोने का ताबीज़",
"Лучший оберег Ордена. Шанс поимки ×2.":"संघ का सबसे अच्छा ताबीज़। पकड़ने का मौक़ा ×2।",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"आत्माओं को शहद बहुत पसंद है। आत्मा को शांत करता है: एक फेंक के लिए पकड़ने का मौक़ा ×1.5।",
"Подорожник":"जड़ी-पत्ता",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"घाव पर पत्ता रखो — और आराम मिला। आत्मा को एक-चौथाई सेहत लौटाता है।",
"Целебный отвар":"औषधि-काढ़ा",
"Травы Велеса, сваренные в воде из источника. Возвращает духу 60% здоровья.":"झरने के पानी में उबली वेलेस की जड़ी-बूटियाँ। आत्मा को 60% सेहत लौटाता है।",
"Мёртвая вода":"म्योर्तवाया वोदा",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"दुर्लभ परीकथा का पानी, जो सबसे गहरे घाव भी जोड़ देता है। बेहोश आत्मा 4 घंटे पहले उठेगी। होश वाली आत्माओं का इलाज नहीं करता।",
"Живая вода":"ज़िवाया वोदा",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"आत्मा की आधी सेहत लौटाता है, और दरार में — लड़ाई के बीच ही इलाज करता है। बेहोश आत्मा को नहीं उठाता।",
"Ладан":"लोबान",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"धुआँ आत्माओं को खींचता है: 30 मिनट तक आसपास दोगुनी आत्माएँ।",
"Дальний пропуск":"दूर का पास",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"संघ का परवाना: तुमसे 5 किमी तक की दरार बिना पास गए बंद करो। संघ रोज़ एक देता है।",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"राहों के भँवर वाला संघ का छल्ला: इंतज़ार किए बिना विश्व एटलस की किसी भी जगह तुरंत पहुँचो। लगातार सातवें दिन एक तोहफ़े में मिलता है।",
"Настой опыта":"XP अर्क",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"वेलेस की जड़ी-बूटियों पर शहद का अर्क: 24 घंटे XP एक चौथाई ज़्यादा।",
