"Победа засчитана, но пока шёл бой, в Святилище сменились защитники.":"जीत दर्ज हुई, पर लड़ाई के दौरान पवित्र स्थान पर रक्षक बदल गए।",
"«Достойно, Ловчий», — {0} склоняет голову. Святилище «{1}» освящено тобой до конца дня.":"“शाबाश, शिकारी,” — {0} सिर झुकाता है। पवित्र स्थान “{1}” दिन के अंत तक तुम्हारे द्वारा पवित्र है।",
"Победа!":"जीत!",
"Поставь своего защитника — и Святилище перейдёт твоему клану.":"अपना रक्षक रखो — और पवित्र स्थान तुम्हारे दल का हो जाएगा।",
"Поражение":"हार",
