"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"प्रोग्रेस अकाउंट में रहेगी — उसी लॉग इन से वापस आ सकते हो। इस डिवाइस पर नया गेस्ट गेम शुरू होगा।",
