"Прогресс хранится на сервере игры, поэтому нужен интернет.":"प्रोग्रेस गेम सर्वर पर रहती है, इसलिए इंटरनेट चाहिए।",
"Проверяю обновления…":"अपडेट जाँच रहे हैं…",
