"Седьмой день! Завтра круг начнётся снова — серия продолжается.":"सातवाँ दिन! कल से चक्र फिर शुरू होगा — सिलसिला जारी रहेगा।",
"Не пропускай день — иначе серия начнётся сначала.":"एक दिन भी मत छोड़ना — वरना सिलसिला फिर से शुरू होगा।",
