"Вершина пути":"राह का शिखर",
"Максимальный уровень Ловчего":"शिकारी का सबसे ऊँचा लेवल",
"Сегодня получено {0} опыта — полностью до {1}":"आज {0} XP मिला — {1} तक पूरा",
"Сегодня получено {0} опыта — дальше вполовину до {1}":"आज {0} XP मिला — आगे {1} तक आधा",
"Сегодня получено {0} опыта — дальше на четверть":"आज {0} XP मिला — आगे एक चौथाई",
"Опыт отдыха: следующие {0} опыта — вдвое":"आराम XP: अगला {0} XP — दोगुना",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"दिन में XP {0} तक पूरा आता है, फिर {1} तक — आधा, उससे ऊपर — एक चौथाई। ट्यूटोरियल और संघ के बैज हमेशा पूरा XP देते हैं। बिना खेले हर दिन आराम XP जमा होता है ({2}, ज़्यादा से ज़्यादा {3} {4} का): जब तक वह है, XP दोगुना।",
"Звание «{0}»":"उपाधि “{0}”",
"Ты здесь":"तुम यहाँ हो",
"Ты прошёл весь путь!":"तुमने पूरी राह तय कर ली!",
"До {0} уровня — {1} опыта":"लेवल {0} तक — {1} XP",
"дальше: {0} на {1}":"आगे: {1} पर {0}",
"Опыт дают поимки, источники, разломы, святилища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"XP पकड़ने, स्रोतों, दरारों, पवित्र स्थान और क्वेस्ट से मिलता है। लेवल के साथ तुम्हारी आत्माएँ भी बढ़ती हैं: उनकी शक्ति शिकारी के लेवल +5 तक बढ़ाई जा सकती है।",
