"Ищу настоящие места вокруг — Источники и Святилища появятся через несколько секунд":"आसपास असली जगहें ढूँढ रहे हैं — स्रोत और पवित्र स्थान कुछ सेकंड में दिखेंगे",
"Сервер мест не ответил":"स्थानों का सर्वर जवाब नहीं दे रहा",
"Посылка из Ордена":"संघ का पार्सल",
"Поблизости пока нет ни одного Источника, поэтому Орден раз в день присылает припасы: {0}.":"पास में अभी एक भी स्रोत नहीं है, इसलिए संघ रोज़ सामान भेजता है: {0}।",
"Спасибо":"शुक्रिया",
"На проверке":"जाँच में",
"Одобрено":"मंज़ूर",
"Отклонено":"नामंज़ूर",
"Места":"जगहें",
"Источники и Святилища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"स्रोत और पवित्र स्थान असली जगहों पर होते हैं। पास में कोई दिलचस्प जगह जानते हो? उसे सुझाओ!",
