"Орден вручает тебе кокон. Он уже теплеет…":"संघ तुम्हें एक कोकून सौंपता है। वह गर्म होने लगा है…",
"Весь мир — твой":"सारी दुनिया तुम्हारी है",
"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"महा-उलझन ने दुनिया की राहें उलझा दीं, और ताबीज़ संघ ने शिकारियों के लिए द्वार खोल दिए: विश्व एटलस में धरती का कोई भी कोना चुनो — वहीं से तुम्हारा शिकार शुरू होगा। नक्शे पर जॉयस्टिक से चलो, और नए इलाक़ों में एटलस से जाओ। गेम को तुम्हारे फ़ोन की असली लोकेशन नहीं चाहिए। प्रगति गेम सर्वर पर रहती है और सिर्फ़ तुम्हारे लिए है; सर्वर हर क़दम जाँचता है, इसलिए इंटरनेट चाहिए। चुने गए इलाक़े की नक्शे की जगहें और मौसम OpenStreetMap और Open-Meteo से आते हैं (मौसम सेटिंग्स में बंद किया जा सकता है)।",
"Уже играешь?":"पहले से खेल रहे हो?",
"Войди — и твой прогресс откроется на этом устройстве":"लॉग इन करो — और तुम्हारी प्रोग्रेस इस डिवाइस पर खुल जाएगी",
"Назови себя":"अपना नाम बताओ",
"Коснись, чтобы попробовать ещё раз":"फिर से कोशिश करने के लिए छुओ",
"Новое приложение":"नया ऐप",
"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"गेम रूस में अपने सर्वर पर चला गया है — <b>duholov.ru</b>। इसके लिए नया ऐप आया है: उसे फिर से इंस्टॉल करना होगा।",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"लॉग इन जोड़ो: मेनू → सेटिंग्स → अकाउंट (Google, यांडेक्स, VK, Telegram या ईमेल)। इसके बिना गेस्ट प्रोग्रेस ट्रांसफ़र नहीं होगी।",
"Удали это приложение.":"यह ऐप हटाओ।",
"Скачай и установи новое — войди тем же способом.":"नया डाउनलोड करके इंस्टॉल करो — उसी तरीक़े से लॉग इन करो।",
